PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .pred  %p0, %p1, %p2, %p3, %p4;
    .reg .u32   %rTid, %rNT, %rBidY, %rM, %rK, %rKiter, %rStride, %rIdx2;
    .reg .u64   %rdA, %rdB, %rdC, %rdRowK, %rdKiter, %rdAelem, %rdAoffB, %rdAaddr;
    .reg .u64   %rdBoffB, %rdBaddr, %rdSbase, %rdTidOff, %rdSaddr, %rdIdx2Off, %rdSaddr2;
    .reg .u64   %rdRow, %rdCoffB, %rdCaddr;
    .reg .f32   %fAcc, %fA, %fB, %fT0, %fT1, %fRes;

    // Shared memory for block reduction: supports up to 1024 threads (4096 bytes)
    .shared .align 4 .b8 sdata[4096];

    // Load parameters
    ld.param.u64   %rdA, [A_ptr];
    ld.param.u64   %rdB, [B_ptr];
    ld.param.u64   %rdC, [C_ptr];
    ld.param.u32   %rM, [M];
    ld.param.u32   %rK, [K];

    // Thread/block info
    mov.u32        %rTid, %tid.x;
    mov.u32        %rNT,  %ntid.x;
    mov.u32        %rBidY, %ctaid.y;

    // Bounds check for row index
    setp.ge.u32    %p0, %rBidY, %rM;
    @%p0 bra       DONE;

    // Compute base element offset row * K in 64-bit
    mul.wide.u32   %rdRowK, %rBidY, %rK;   // 64-bit: row*K

    // Initialize accumulator
    mov.f32        %fAcc, 0f00000000;

    // Loop over K dimension with stride = blockDim.x
    mov.u32        %rKiter, %rTid;

LOOP_COND:
    setp.ge.u32    %p1, %rKiter, %rK;
    @%p1 bra       LOOP_END;

    // k in 64-bit
    cvt.u64.u32    %rdKiter, %rKiter;

    // A index: (row*K + k)
    add.s64        %rdAelem, %rdRowK, %rdKiter;
    shl.b64        %rdAoffB, %rdAelem, 2;     // *4 bytes
    add.s64        %rdAaddr, %rdA, %rdAoffB;

    // B index: k
    shl.b64        %rdBoffB, %rdKiter, 2;     // *4 bytes
    add.s64        %rdBaddr, %rdB, %rdBoffB;

    // Loads
    ld.global.f32  %fA, [%rdAaddr];
    ld.global.f32  %fB, [%rdBaddr];

    // FMA accumulate
    fma.rn.f32     %fAcc, %fA, %fB, %fAcc;

    // k += blockDim.x
    add.u32        %rKiter, %rKiter, %rNT;
    bra            LOOP_COND;

LOOP_END:
    // Shared memory base
    mov.u64        %rdSbase, sdata;

    // Store partial sum to shared memory at sdata[tid]
    mul.wide.u32   %rdTidOff, %rTid, 4;
    add.s64        %rdSaddr, %rdSbase, %rdTidOff;
    st.shared.f32  [%rdSaddr], %fAcc;

    // Sync before reduction
    bar.sync 0;

    // s = blockDim.x >> 1
    shr.u32        %rStride, %rNT, 1;

REDUCE_LOOP_COND:
    setp.eq.u32    %p2, %rStride, 0;
    @%p2 bra       REDUCE_DONE;

    // If (tid < s) then reduce with neighbor
    setp.ge.u32    %p3, %rTid, %rStride;
    @%p3 bra       REDUCE_SKIP;

    // Load self
    ld.shared.f32  %fT0, [%rdSaddr];

    // Neighbor index = tid + s
    add.u32        %rIdx2, %rTid, %rStride;
    mul.wide.u32   %rdIdx2Off, %rIdx2, 4;
    add.s64        %rdSaddr2, %rdSbase, %rdIdx2Off;

    // Load neighbor and add
    ld.shared.f32  %fT1, [%rdSaddr2];
    add.f32        %fT0, %fT0, %fT1;

    // Store back
    st.shared.f32  [%rdSaddr], %fT0;

REDUCE_SKIP:
    // Sync all threads before next step
    bar.sync 0;

    // s >>= 1
    shr.u32        %rStride, %rStride, 1;
    bra            REDUCE_LOOP_COND;

REDUCE_DONE:
    // Thread 0 writes the result to C[row]
    setp.ne.u32    %p4, %rTid, 0;
    @%p4 bra       DONE;

    // Load final sum from sdata[0]
    ld.shared.f32  %fRes, [%rdSbase];

    // C address = C + row*4
    cvt.u64.u32    %rdRow, %rBidY;
    shl.b64        %rdCoffB, %rdRow, 2;
    add.s64        %rdCaddr, %rdC, %rdCoffB;

    st.global.f32  [%rdCaddr], %fRes;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

