            raise RuntimeError("Expected B shape (K,1) matching A.shape[1].")

        A_c = A.contiguous()
        B_c = B.contiguous()
        C = torch.empty((M, 1), device=A_c.device, dtype=A_c.dtype)

        module = _get_ptx_module()

