            "the_entry_name",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, 1, 1),
            arguments=[A_c, B_c, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A_c.device),
        )
        return C

